script:
frappe.ui.form.on('Commande Impression', {
    refresh: function(frm) {
        frm.set_value('total', (frm.doc.prix_unitaire || 0) * (frm.doc.quantite || 0));
    },
    prix_unitaire: function(frm) {
        frm.set_value('total', (frm.doc.prix_unitaire || 0) * (frm.doc.quantite || 0));
    },
    quantite: function(frm) {
        frm.set_value('total', (frm.doc.prix_unitaire || 0) * (frm.doc.quantite || 0));
    },
    workflow_state: function(frm) {
        if (frm.doc.workflow_state === 'Approved') {
            frappe.msgprint(`Enregistrement journalier : Prix Unitaire - ${frm.doc.prix_unitaire} FCFA, Quantité - ${frm.doc.quantite}, Total - ${frm.doc.total} FCFA`);
        }
    }
});
